import re

def parse_version(v: str):
    if not isinstance(v, str):
        raise ValueError(f"Invalid version: {v!r}")
    parts = v.split('.')
    if len(parts) != 3:
        raise ValueError(f"Invalid version: {v!r}")
    nums = []
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"Invalid version: {v!r}")
        if len(p) > 1 and p[0] == '0':
            raise ValueError(f"Invalid version: {v!r}")
        nums.append(int(p))
    return tuple(nums)


def satisfies(version: str, spec: str) -> bool:
    v = parse_version(version)

    if not isinstance(spec, str):
        raise ValueError(f"Invalid spec: {spec!r}")
    spec = spec.strip()
    if not spec:
        raise ValueError("Empty spec")

    # Caret range
    if spec.startswith('^'):
        base = parse_version(spec[1:])
        X, Y, Z = base
        low = base
        if X > 0:
            high = (X + 1, 0, 0)
        elif Y > 0:
            high = (0, Y + 1, 0)
        else:
            high = (0, 0, Z + 1)
        return low <= v < high

    # Tilde range
    if spec.startswith('~'):
        base = parse_version(spec[1:])
        X, Y, Z = base
        low = base
        high = (X, Y + 1, 0)
        return low <= v < high

    # Exact version (no operator)
    if re.fullmatch(r'\d+\.\d+\.\d+', spec):
        base = parse_version(spec)
        return v == base

    # Conjunction of comparators
    tokens = spec.split()
    if not tokens:
        raise ValueError(f"Malformed spec: {spec!r}")

    pattern = re.compile(r'^(>=|<=|>|<|=)(\d+\.\d+\.\d+)$')
    results = []
    for tok in tokens:
        m = pattern.match(tok)
        if not m:
            raise ValueError(f"Malformed spec: {spec!r}")
        op, ver_str = m.groups()
        base = parse_version(ver_str)
        if op == '>=':
            results.append(v >= base)
        elif op == '<=':
            results.append(v <= base)
        elif op == '>':
            results.append(v > base)
        elif op == '<':
            results.append(v < base)
        elif op == '=':
            results.append(v == base)
        else:
            raise ValueError(f"Malformed spec: {spec!r}")

    return all(results)
